}
function envv(string $key, string $fallback=''): string { $v=getenv($key); return $v===false?$fallback:(string)$v; }
function reply(int $status, array $body): never { http_response_code($status); echo json_encode($body, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit; }
function cleanv($v,int $max): string { $s=trim(preg_replace('/[\x00-\x1F\x7F]/u',' ',(string)($v??'')));return function_exists('mb_substr')?mb_substr($s,0,$max):substr($s,0,$max); }
