function body(): array { $raw=file_get_contents('php://input'); if(strlen($raw)>32768) reply(413,['error'=>'Request too large.']); $v=json_decode($raw?:'{}',true); if(!is_array($v)) reply(400,['error'=>'Invalid JSON.']); return $v; }
function datafile(string $name): string { global $root; $dir=$root.'/data'; if(!is_dir($dir)) @mkdir($dir,0700,true); return $dir.'/'.$name; }
function local_rows(string $name): array { $v=json_decode((string)@file_get_contents(datafile($name)),true); return is_array($v)?$v:[]; }
function save_rows(string $name,array $rows): void { $file=datafile($name); $tmp=$file.'.'.bin2hex(random_bytes(5)).'.tmp'; file_put_contents($tmp,json_encode($rows,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX); chmod($tmp,0600); rename($tmp,$file); }
function http_json(string $url,string $method='GET',?array $payload=null,array $headers=[]): array {
    if(!function_exists('curl_init')) throw new RuntimeException('PHP cURL extension must be enabled in Hostinger.');
    $ch=curl_init($url); $h=array_merge(['Content-Type: application/json','Accept: application/json'],$headers);
    curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$h,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>20]);
    if($payload!==null) curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
    $raw=curl_exec($ch); $code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE); $err=curl_error($ch); curl_close($ch);
    if($raw===false) throw new RuntimeException('Remote service request failed: '.$err);
    $out=json_decode($raw,true); if($code<200||$code>=300) throw new RuntimeException(cleanv($out['error']['description']??$out['message']??"Remote service returned HTTP $code.",300));
    return is_array($out)?$out:[];
}
function db_request(string $table,string $method='GET',array $query=[],?array $payload=null): array {
    $url=rtrim(envv('SUPABASE_URL'),'/'); $key=envv('SUPABASE_SECRET_KEY',envv('SUPABASE_SERVICE_ROLE_KEY'));
    if(!preg_match('~^https://[a-z0-9-]+\.supabase\.co$~i',$url)||!preg_match('/^(sb_secret_|eyJ)/',$key)) throw new RuntimeException('Supabase is not configured.');
    $qs=$query?('?'.http_build_query($query,'','&',PHP_QUERY_RFC3986)):'';
    $headers=['apikey: '.$key,'Authorization: Bearer '.$key]; if($payload!==null)$headers[]='Prefer: return=representation';
    return http_json($url.'/rest/v1/'.$table.$qs,$method,$payload,$headers);
}
function db_enabled(): bool { $u=envv('SUPABASE_URL');$k=envv('SUPABASE_SECRET_KEY',envv('SUPABASE_SERVICE_ROLE_KEY'));return (bool)(preg_match('~^https://[a-z0-9-]+\.supabase\.co$~i',$u)&&preg_match('/^(sb_secret_|eyJ)/',$k)); }
function find_user(string $email): ?array { if(db_enabled()){ $r=db_request('store_users','GET',['select'=>'id,name,email,salt,password_hash,created_at','email'=>'eq.'.$email,'limit'=>'1']);return $r[0]??null;} foreach(local_rows('users.json') as $u)if(normemail($u['email']??'')===$email)return $u;return null; }
