function all_orders(?string $email=null,int $limit=500): array { if(db_enabled()){ $q=['select'=>'id,customer_email,data,created_at','order'=>'created_at.desc','limit'=>(string)$limit];if($email!==null)$q['customer_email']='eq.'.normemail($email);return array_values(array_map(fn($r)=>$r['data'],$x=db_request('store_orders','GET',$q))); } $rows=local_rows('orders.json');if($email!==null)$rows=array_values(array_filter($rows,fn($o)=>normemail($o['customer']['email']??'')===normemail($email)));return array_slice($rows,0,$limit); }
function store_order(array $o): void { if(db_enabled()){db_request('store_orders','POST',[] ,['id'=>$o['id'],'customer_email'=>normemail($o['customer']['email']),'data'=>$o,'created_at'=>$o['createdAt']]);return;} $rows=local_rows('orders.json');array_unshift($rows,$o);save_rows('orders.json',array_slice($rows,0,500)); }
function current_user(): ?array { return isset($_SESSION['mlang_user'])&&is_array($_SESSION['mlang_user'])?$_SESSION['mlang_user']:null; }
function public_user(array $u): array { return ['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>(normemail($u['email'])===normemail(envv('ADMIN_EMAIL'))&&envv('ADMIN_EMAIL')?'admin':'customer')]; }
function cart_totals($lines,$coupon): array {
    $catalog=json_decode((string)@file_get_contents(__DIR__.'/shared/catalog.json'),true);$products=[];foreach(($catalog['PRODUCTS']??[]) as $p)$products[$p['id']]=$p;$sizes=$catalog['PRODUCT_SIZES']??[];
    if(!is_array($lines)||count($lines)<1||count($lines)>20)throw new RuntimeException('Your bag is empty or contains too many line items.');$items=[];$qtys=[];
    foreach($lines as $line){$id=(string)($line['id']??'');$qty=filter_var($line['qty']??null,FILTER_VALIDATE_INT);$size=(string)($line['size']??'');$p=$products[$id]??null;if(!$p||!in_array($size,$sizes,true)||$qty===false||$qty<1||$qty>5)throw new RuntimeException('One of the items in your bag is invalid.');$qtys[$id]=($qtys[$id]??0)+$qty;if($qtys[$id]>(int)$p['stock'])throw new RuntimeException($p['name'].' has only '.$p['stock'].' pieces available.');$items[]=['id'=>$id,'sku'=>$p['sku'],'name'=>$p['name'],'size'=>$size,'qty'=>$qty,'unitPrice'=>(int)$p['price'],'lineTotal'=>(int)$p['price']*$qty];}
    $subtotal=array_sum(array_column($items,'lineTotal'));$discount=$coupon==='WELCOME10'?(int)round($subtotal*.1):0;$shipping=$subtotal-$discount>=3000?0:99;return ['items'=>$items,'subtotal'=>$subtotal,'discount'=>$discount,'shipping'=>$shipping,'total'=>$subtotal-$discount+$shipping];
}
function customer_data($v): array { $c=['name'=>cleanv($v['name']??'',100),'email'=>normemail($v['email']??''),'phone'=>cleanv($v['phone']??'',24),'address'=>cleanv($v['address']??'',240),'city'=>cleanv($v['city']??'',100),'state'=>cleanv($v['state']??'',100),'pincode'=>cleanv($v['pincode']??'',6),'country'=>'India'];if(strlen($c['name'])<2||!filter_var($c['email'],FILTER_VALIDATE_EMAIL)||!preg_match('/^[0-9+ ()-]{8,16}$/',$c['phone'])||strlen($c['address'])<5||strlen($c['city'])<2||strlen($c['state'])<2||!preg_match('/^[0-9]{6}$/',$c['pincode']))throw new RuntimeException('Please check your contact and delivery details.');return $c; }
function make_order(array $totals,array $customer,string $method,string $status): array { return ['id'=>'ML-'.substr((string)time(),-8).'-'.strtoupper(bin2hex(random_bytes(2))),'receipt'=>strtolower($method).'_'.bin2hex(random_bytes(10)),'status'=>$status,'paymentMethod'=>$method,'items'=>$totals['items'],'subtotal'=>$totals['subtotal'],'discount'=>$totals['discount'],'shipping'=>$totals['shipping'],'total'=>$totals['total'],'currency'=>'INR','customer'=>$customer,'policyAccepted'=>true,'createdAt'=>gmdate('c'),'shippingInfo'=>null,'emailStatus'=>'pending_setup']; }
