function sr_enabled(): bool { $email=envv('SHIPROCKET_API_EMAIL');$pass=envv('SHIPROCKET_API_PASSWORD');$pickup=envv('SHIPROCKET_PICKUP_LOCATION');$dims=[envv('SHIPROCKET_PACKAGE_LENGTH_CM'),envv('SHIPROCKET_PACKAGE_BREADTH_CM'),envv('SHIPROCKET_PACKAGE_HEIGHT_CM'),envv('SHIPROCKET_PACKAGE_WEIGHT_KG')];foreach($dims as $d)if(!is_numeric($d)||(float)$d<=0)return false;return (bool)(filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($pass)>8&&$pickup!==''&&!preg_match('/(replace|placeholder|example\.com)/i',$email.' '.$pass.' '.$pickup)); }
function sr_request(string $route,string $method='GET',?array $payload=null): array {
    if(empty($_SESSION['shiprocket_token'])||($_SESSION['shiprocket_expiry']??0)<time()){$a=http_json('https://apiv2.shiprocket.in/v1/external/auth/login','POST',['email'=>envv('SHIPROCKET_API_EMAIL'),'password'=>envv('SHIPROCKET_API_PASSWORD')]);if(empty($a['token']))throw new RuntimeException('Shiprocket login failed. Check API user credentials.');$_SESSION['shiprocket_token']=$a['token'];$_SESSION['shiprocket_expiry']=time()+7*86400;}
