','awb'=>(string)$awb,'carrierStatus'=>cleanv($a['courier_name']??'AWB assigned',80),'shiprocketOrderId'=>(string)($created['order_id']??$created['data']['order_id']??''),'shipmentId'=>(string)$shipment,'pickupStatus'=>$pickup,'pickupMessage'=>$message];}
